1: /** @module @category API */
2: import type { Session } from '@openmrs/esm-api';
3: import { getSessionStore } from '@openmrs/esm-api';
4: import { useState, useEffect, useRef } from 'react';
5: 
6: let promise: undefined | Promise<Session>;
7: 
8: /**
9:  * Gets the current user session information. Returns an object with
10:  * property `authenticated` == `false` if the user is not logged in.
11:  *
12:  * Uses Suspense. This hook will always either return a Session object
13:  * or throw for Suspense. It will never return `null`/`undefined`.
14:  *
15:  * @returns Current user session information
16:  */
17: export function useSession(): Session {
18:   // We have two separate variables for the session.
19:   //
20:   // `session` is a temporary variable, which starts as `null` every time this
21:   // hook is executed. It is important that we can set and return this
22:   // variable synchronously, because every time we `throw` for Suspense, this
23:   // hook will unmount and a new instance will be created, destroying whatever
24:   // state existed. Thus, if this hook were to try to always set and return
25:   // `stateSession`, it would cause an infinite loop:
26:   //   1. instance A mounts
27:   //   2. instance A receives value, calls `setStateSession`
28:   //   3. instance A throws
29:   //   4. instance A unmounts
30:   //   5. instance B mounts
31:   //   ...
32:   // What would happen if we moved `session` to the module scope, so that it
33:   // could be re-used across instances of this hook? Then we would have no way
34:   // to tell whether the session was fresh.
35:   //
36:   // `stateSession` is React state, which is needed to update components using
37:   // this hook when the session changes.
38:   const unsubscribe = useRef<undefined | (() => void)>();
39:   const [stateSession, setStateSession] = useState<Session | null>(null);
40:   let session: Session | null = null;
41: 
42:   if (!stateSession) {
43:     if (!promise) {
44:       // If we haven't created a promise to throw yet, do that.
45:       // current-user.ts handles the initial session fetch as soon as `getSessionStore()`
46:       // is called. We just need to call it and set up a listener for when session data
47:       // is loaded. As soon as we have the initial session data, we remove this initial
48:       // store subscription so we can set up the "ongoing" one later.
49:       promise = new Promise<Session>((resolve) => {
50:         const handleNewSession = ({ loaded, session: newSession }) => {
51:           if (loaded) {
52:             resolve(newSession);
53:             session = newSession;
54:             if (unsubscribe.current) {
55:               unsubscribe.current();
56:               unsubscribe.current = undefined;
57:             }
58:           }
59:         };
60:         handleNewSession(getSessionStore().getState());
61:         if (!session) {
62:           unsubscribe.current = getSessionStore().subscribe(handleNewSession);
63:         }
64:       });
65:     } else {
66:       // However, if we have created a promise to throw, but there's no `stateSession`
67:       // yet, then it's probably just this hook's first render. Check to see if
68:       // there's already a session that we can return.
69:       const currentState = getSessionStore().getState();
70:       if (currentState.loaded) {
71:         session = currentState.session;
72:       }
73:     }
74: 
75:     // If the session got set synchronously in the above block, then we can just
76:     // return it rather than throwing. Otherwise, throw for Suspense.
77:     if (session) {
78:       setStateSession(session);
79:     } else {
80:       throw promise;
81:     }
82:   }
83: 
84:   // Once this hook is established (no longer throwing and getting re-created)
85:   // we need to set up a subscription that will update its value the good
86:   // old-fashioned React way. We are re-using the `unsubscribe` ref from the
87:   // initial subscription, which should have been vacated by the first time we
88:   // get here.
89:   useEffect(() => {
90:     if (!unsubscribe.current) {
91:       unsubscribe.current = getSessionStore().subscribe(({ loaded, session: newSession }) => {
92:         if (loaded) {
93:           session = newSession;
94:           setStateSession(newSession);
95:         }
96:       });
97:     }
98:     return () => {
99:       if (unsubscribe.current) {
100:         unsubscribe.current();
101:         unsubscribe.current = undefined;
102:       }
103:     };
104:   }, []);
105: 
106:   const result = stateSession || session;
107:   if (!result) {
108:     if (promise) {
109:       console.warn('useSession is in an unexpected state. Attempting to recover.');
110:       throw promise;
111:     } else {
112:       throw Error('useSession is in an invalid state.');
113:     }
114:   }
115:   return result;
116: }
117: 
118: /**
119:  * For testing.
120:  */
121: export function __cleanup() {
122:   promise = undefined;
123: }
