1: /** @module @category API */
2: import { reportError } from '@openmrs/esm-error-handling';
3: import { createGlobalStore } from '@openmrs/esm-state';
4: import { isUndefined } from 'lodash-es';
5: import { OpenmrsFetchError, openmrsFetch, restBaseUrl, sessionEndpoint } from './openmrs-fetch';
6: import type { LoggedInUser, SessionLocation, Privilege, Role, Session, FetchResponse } from './types';
7: 
8: export type SessionStore = LoadedSessionStore | UnloadedSessionStore;
9: 
10: export type LoadedSessionStore = {
11:   loaded: true;
12:   session: Session;
13: };
14: 
15: export type UnloadedSessionStore = {
16:   loaded: false;
17:   session: null;
18:   /** Set when fetching the session failed before any session had loaded. */
19:   error?: Error;
20:   /**
21:    * Set alongside `error`. `true` when the backend appears to be still starting up rather than broken:
22:    * it redirected the session request to its initial setup page, or its gateway answered with a 502
23:    * shortly after the page loaded.
24:    */
25:   initializing?: boolean;
26: };
27: 
28: /** @internal */
29: export const sessionStore = createGlobalStore<SessionStore>('session', {
30:   loaded: false,
31:   session: null,
32: });
33: 
34: /**
35:  * The upper bound on how old the session handed to a reader may be. It is measured from the moment a
36:  * fetch is *started*, not from the moment its response lands, so the session a reader sees is always
37:  * strictly newer than this.
38:  */
39: const sessionMaxAgeMillis = 60 * 1000;
40: 
41: let lastFetchTimeMillis = 0;
42: 
43: /**
44:  * How long after the first session fetch a 502 is taken to mean that the backend is still starting up. A
45:  * gateway answers with a 502 until the backend has deployed, which can take a few minutes after a restart.
46:  */
47: const startupGracePeriodMillis = 3 * 60 * 1000;
48: 
49: let firstFetchTimeMillis: number | undefined;
50: let inFlightRefresh: Promise<SessionStore> | null = null;
51: 
52: /**
53:  * Fetches the session if the store is unloaded or its session is older than `sessionMaxAgeMillis`.
54:  * Returns `null` only when the store already holds a session fresh enough to be read as-is, so a
55:  * caller that gets a promise back must wait for it rather than read the store.
56:  *
57:  * A fetch already in flight is joined rather than duplicated. This is what keeps `sessionMaxAgeMillis`
58:  * an upper bound: while a fetch is running, the store still holds the previous session, and returning
59:  * that would hand back data older than the bound allows.
60:  *
61:  * The returned promise rejects if the fetch fails, but the rejection is already handled and reported,
62:  * so a caller that only needs the fetch started can ignore it.
63:  */
64: function refreshSessionIfStale(): Promise<SessionStore> | null {
65:   if (inFlightRefresh) {
66:     return inFlightRefresh;
67:   }
68: 
69:   if (sessionStore.getState().loaded && lastFetchTimeMillis >= Date.now() - sessionMaxAgeMillis) {
70:     return null;
71:   }
72: 
73:   return refetchCurrentUser();
74: }
75: 
